//! Checks the merge and the shape split against QuPath **on real tissue**.
//!
//! Fixture generated by `parity/java/MergeAndSplitTile.java` via
//! `./parity/record-merge-tiles.sh`, which needs a slide. Sibling of
//! `parity_merge_and_split.rs`, which pins the same two stages on hand-built
//! shapes and on random fields and needs nothing.
//!
//! **Why a second fixture for one pair of stages.** `DIVERGENCES.md` D-009
//! measures three regions of CMU-1 small enough to be a single tile — no seams,
//! so D-008 cannot apply — and finds the count gap concentrated in exactly these
//! two stages, and only on clumped tissue: the merge keeps 0.557 and 0.560 of
//! its input on the two regions that agree with QuPath and 0.439 on the one that
//! does not, and the split then recovers 1.57x and 1.57x against 2.16x. Both
//! stages do about twice the work there. `MergeAndSplit.json`'s largest case is
//! 96x96 of blurred noise, and its hand-built cases are disks and bars: nothing
//! in it is clumped, so the regime that carries the gap was unpinned.
//!
//! **What this can and cannot settle.** Both sides are given the *same* input
//! mask — the one QuPath's own chain produced on that crop — so this isolates
//! the pair completely. Agreement says the merge and the split are not where the
//! gap is and sends the search upstream; disagreement localises it to a pixel.
//! What it cannot do is tell us whether the *input* mask is the one QuPath's
//! upstream would hand us, which is a different question and a different
//! fixture.
//!
//! **Crops from both regions, not only the divergent one.** Four from the region
//! that disagrees at 1.1130 and four from one that agrees at 1.0177 — the claim
//! under test is a difference between two regimes, and a recording of one
//! regime cannot say whether the stage is wrong or the input is unusual. The
//! same reason the browser's hover fill needed three layouts rather than one.

use qupath_pipeline::{FOREGROUND, Merger};
use qupath_watershed::{DistanceMap, RegionTracer, Segmenter};

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/MergeAndSplitTile.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Unpacks one bit per pixel, little-endian within a byte, into 0 or 255.
///
/// The recorder packs because every mask here is binary and a 319x319 crop
/// written as `[0, 255, 0, ...]` is forty times the bytes for no more
/// information — eight crops of five masks would be a 40 MB fixture rather than
/// a 1 MB one.
fn unpack(hex: &str, pixels: usize) -> Vec<u8> {
    assert_eq!(
        hex.len(),
        pixels.div_ceil(8) * 2,
        "a packed mask of {pixels} pixels should be {} hex characters, got {}",
        pixels.div_ceil(8) * 2,
        hex.len(),
    );
    let mut out = Vec::with_capacity(pixels);
    for chunk in hex.as_bytes().chunks(2) {
        let byte =
            u8::from_str_radix(std::str::from_utf8(chunk).expect("ascii"), 16).expect("a hex byte");
        for bit in 0..8 {
            if out.len() == pixels {
                break;
            }
            out.push(if byte & (1 << bit) != 0 {
                FOREGROUND
            } else {
                0
            });
        }
    }
    out
}

/// Turns the recorded `bpLoG` back into a Laplacian that thresholds to it.
///
/// The fixture records `SimpleThresholding.thresholdAbove(fpLoG, 0.0)` rather
/// than the float image, because that mask is all the `AND` can see. Any pair of
/// values straddling zero reconstructs it, and the port takes the float image so
/// that the pipeline does not have to materialise the mask.
fn laplacian_from(mask: &[u8]) -> Vec<f32> {
    mask.iter()
        .map(|&v| if v != 0 { 1.0 } else { -1.0 })
        .collect()
}

/// The merge and the split reproduce QuPath's masks on real tissue.
#[test]
fn matches_qupath_on_real_tiles() {
    let path = fixture();
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; run ./parity/record-merge-tiles.sh",
            path.display()
        )
    });
    let (tiles, _) = between(&text, "\"tiles\": [", "\n  ]\n}", 0);

    let mut merger = Merger::new();
    let mut tracer = RegionTracer::new();
    let mut distances = DistanceMap::new();
    let mut segmenter = Segmenter::new();

    let mut count = 0usize;
    let mut substantial = 0usize;
    let mut merged_seen = 0u32;
    let mut objects_seen = 0u32;
    // Input, merged and split totals per regime, for the signature check at
    // the end.
    let mut sparse = (0u32, 0u32, 0u32);
    let mut dense = (0u32, 0u32, 0u32);
    let mut at = 0usize;
    while let Some(start) = tiles[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(tiles, "\"name\": \"", "\"", from);
        let (width, next) = scalar(tiles, "width", next);
        let (height, next) = scalar(tiles, "height", next);
        let (after_intensity, next) = scalar(tiles, "afterIntensity", next);
        let (expected_merged, next) = scalar(tiles, "mergedCount", next);
        let (expected_objects, next) = scalar(tiles, "objects", next);
        let (binary_hex, next) = between(tiles, "\"binary\": \"", "\"", next);
        let (log_hex, next) = between(tiles, "\"logMask\": \"", "\"", next);
        let (merged_hex, next) = between(tiles, "\"merged\": \"", "\"", next);
        let (maxima_hex, next) = between(tiles, "\"maxima\": \"", "\"", next);
        let (segmented_hex, next) = between(tiles, "\"segmented\": \"", "\"", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let pixels = width * height;

        let mut binary = unpack(binary_hex, pixels);
        let log = laplacian_from(&unpack(log_hex, pixels));
        let their_merged = unpack(merged_hex, pixels);
        let their_maxima = unpack(maxima_hex, pixels);
        let their_segmented = unpack(segmented_hex, pixels);

        let found = merger.merge(&mut binary, &log, width, &mut tracer);

        // Reported as a count and a first position rather than as one
        // assertion per pixel: a real tile that disagreed would otherwise
        // print the first of possibly thousands of differing pixels and say
        // nothing about whether it was one stray pixel or half the crop.
        let differing = |ours: &[u8], theirs: &[u8]| -> Option<(usize, usize, u8, u8)> {
            let count = ours.iter().zip(theirs).filter(|(a, b)| a != b).count();
            ours.iter()
                .zip(theirs)
                .position(|(a, b)| a != b)
                .map(|at| (at, count, ours[at], theirs[at]))
        };

        if let Some((at, differing, ours, theirs)) = differing(&binary, &their_merged) {
            panic!(
                "{name}: the merge differs in {differing} of {pixels} pixels; \
                 the first is ({}, {}), which merges to {ours} where QuPath has {theirs}",
                at % width,
                at / width,
            );
        }
        assert_eq!(
            u64::from(found),
            index(expected_merged) as u64,
            "{name}: merged region count"
        );

        let mut edm = vec![0.0f32; pixels];
        distances.make_float_edm(&binary, &mut edm, width);

        segmenter.find_maxima(&edm, width);
        if let Some((at, differing, ours, theirs)) =
            differing(segmenter.segmentation(), &their_maxima)
        {
            panic!(
                "{name}: the segmentation differs in {differing} of {pixels} pixels; \
                 the first is ({}, {}), which is {ours} where QuPath has {theirs}",
                at % width,
                at / width,
            );
        }

        segmenter.segment(&edm, &mut binary, width);
        if let Some((at, differing, ours, theirs)) = differing(&binary, &their_segmented) {
            panic!(
                "{name}: the split differs in {differing} of {pixels} pixels; \
                 the first is ({}, {}), which splits to {ours} where QuPath has {theirs}",
                at % width,
                at / width,
            );
        }

        // The number the whole stage exists to change. A mask can match
        // everywhere and still trace to a different number of objects if a
        // single line pixel is misplaced.
        let mut split_regions = vec![0u32; pixels];
        let objects = tracer.trace_mask_into(&binary, &mut split_regions, width);
        assert_eq!(
            u64::from(objects),
            index(expected_objects) as u64,
            "{name}: objects after the split"
        );

        assert_eq!(height * width, pixels);
        if objects > 50 {
            substantial += 1;
        }
        let regime = if name.starts_with("sparse") {
            &mut sparse
        } else {
            &mut dense
        };
        regime.0 += u32::try_from(index(after_intensity)).expect("a recorded count");
        regime.1 += found;
        regime.2 += objects;
        merged_seen += found;
        objects_seen += objects;
        count += 1;
    }

    assert_eq!(count, 8, "expected 8 recorded crops");
    // One crop of the eight lands on glass and comes back empty, which is
    // recorded rather than removed — an empty input is a real state and the
    // merge must leave it empty. The bound is what stops a re-recording that
    // put *every* crop on glass from passing while asserting nothing: the
    // fixture would still match QuPath everywhere, because both sides would be
    // agreeing about a blank image. `record-cell-counts.sh` has the same trap
    // written down, from the sweep that measured four regions of glass.
    assert!(
        substantial >= 6,
        "at least six crops should carry real tissue, not {substantial}"
    );
    assert!(
        objects_seen > merged_seen,
        "the split should raise the object count, {merged_seen} -> {objects_seen}"
    );

    // The two regimes must actually be two regimes.
    //
    // Everything above compares this port against QuPath and would pass just as
    // well on eight crops of the same flat tissue — and then the headline
    // finding, that the pair agrees *where the gap is*, would be resting on
    // crops that were never in that regime. This is the assertion that the
    // fixture is what its name says: the sparse crops must show the merge
    // keeping markedly less of its input and the split recovering markedly
    // more, which is the signature D-009 measured across whole regions
    // (0.439 against 0.557/0.560, and 2.16x against 1.57x).
    //
    // The bounds are loose on purpose. What is being pinned is the *direction*
    // and that the separation is not marginal; the exact ratios are properties
    // of eight particular crops, and a re-recording that moved them slightly
    // should not fail. What must fail is a re-recording where the difference
    // has gone.
    let keep = |(input, merged, _): (u32, u32, u32)| f64::from(merged) / f64::from(input);
    let recover = |(_, merged, objects): (u32, u32, u32)| f64::from(objects) / f64::from(merged);
    assert!(
        keep(sparse) < keep(dense) - 0.1,
        "the sparse crops should bridge markedly more into shared blobs: \
         keep {:.3} sparse against {:.3} dense",
        keep(sparse),
        keep(dense),
    );
    assert!(
        recover(sparse) > recover(dense) + 0.2,
        "the sparse crops should need markedly more splitting back apart: \
         recover {:.3}x sparse against {:.3}x dense",
        recover(sparse),
        recover(dense),
    );
}
